package com.community.residence.common.lease.service;
import com.community.residence.common.lease.entity.LeaseContractTerm;
import com.community.residence.common.payment.entity.LeasePayment;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
import java.time.*;import java.math.BigDecimal;import java.util.*;
class RentScheduleTest {
 LeaseContractTerm term(long id,String start,int months,int price) {var t=new LeaseContractTerm();t.setId(id);t.setStatus("ACTIVE");t.setStartDate(LocalDate.parse(start));t.setEndDate(t.getStartDate().plusMonths(months).minusDays(1));t.setContractMonths(months);t.setMonthlyRent(BigDecimal.valueOf(price));return t;}
 LeasePayment paid(String start,String end,int months) {var p=new LeasePayment();p.setStatus("SUCCESS");p.setMonths(months);p.setPeriodStart(LocalDate.parse(start));p.setPeriodEnd(LocalDate.parse(end));return p;}
 @Test void twelveMonthsPaidOneAllowsOneToEleven() {var schedule=RentSchedule.build(List.of(term(1,"2026-10-15",12,3600)),List.of(paid("2026-10-15","2026-11-14",1)));var q=RentSchedule.quote(schedule,11);assertThat(q.remaining()).isEqualTo(11);assertThat(q.amount()).isEqualByComparingTo("39600");assertThat(q.start()).isEqualTo("2026-11-15");assertThat(q.end()).isEqualTo("2027-10-14");assertThatThrownBy(()->RentSchedule.quote(schedule,12)).hasMessageContaining("1至11");}
 @Test void approvedExtensionIncreasesLimitWithoutPayment() {var schedule=RentSchedule.build(List.of(term(1,"2026-10-15",12,3600),term(2,"2027-10-15",3,3600)),List.of(paid("2026-10-15","2026-11-14",1)));assertThat(RentSchedule.quote(schedule,14).amount()).isEqualByComparingTo("50400");}
 @Test void monthEndRetainsOriginalAnchor() {var first=term(1,"2027-01-31",1,10);var second=term(2,"2027-02-28",1,20);second.setEndDate(LocalDate.parse("2027-03-30"));var schedule=RentSchedule.build(List.of(first,second),List.of());var q=RentSchedule.quote(schedule,2);assertThat(q.end()).isEqualTo("2027-03-30");assertThat(q.amount()).isEqualByComparingTo("30");assertThat(q.slices()).hasSize(2);}
 @Test void crossHistoricalPricesDoesNotUseCurrentPriceForAll() {var schedule=RentSchedule.build(List.of(term(1,"2026-10-15",2,1000),term(2,"2026-12-15",3,2000)),List.of(paid("2026-10-15","2026-11-14",1)));var q=RentSchedule.quote(schedule,4);assertThat(q.amount()).isEqualByComparingTo("7000");assertThat(q.slices()).extracting(RentSchedule.Slice::months).containsExactly(1,3);}
 @Test void allPaidCannotPayAgain() {var s=RentSchedule.build(List.of(term(1,"2026-10-15",2,100)),List.of(paid("2026-10-15","2026-12-14",2)));assertThatThrownBy(()->RentSchedule.quote(s,1)).hasMessageContaining("已缴清");}
 @Test void missingAndDiscontinuousHistoryAreNotGuessed() {var t=term(1,"2026-10-15",12,100);var p=paid("2026-11-15","2026-12-14",1);assertThatThrownBy(()->RentSchedule.build(List.of(t),List.of(p))).hasMessageContaining("空档");p.setPeriodStart(null);assertThatThrownBy(()->RentSchedule.build(List.of(t),List.of(p))).hasMessageContaining("快照");}
 @Test void pendingAndAnomalyDoNotCountAsPaid() {var t=term(1,"2026-10-15",12,100);var p=paid("2026-10-15","2026-11-14",1);p.setStatus("PENDING");assertThat(RentSchedule.quote(RentSchedule.build(List.of(t),List.of(p)),12).remaining()).isEqualTo(12);p.setStatus("SUCCESS");p.setSettlementIssue("REVIEW");assertThat(RentSchedule.quote(RentSchedule.build(List.of(t),List.of(p)),12).remaining()).isEqualTo(12);}
 @Test void versionChangesWithMonthsPaymentOrPrice() {var t=term(1,"2026-10-15",12,100);var s=RentSchedule.build(List.of(t),List.of());var q=RentSchedule.quote(s,1);assertThat(q.version()).isNotEqualTo(RentSchedule.quote(s,2).version());t.setMonthlyRent(BigDecimal.valueOf(101));assertThat(q.version()).isNotEqualTo(RentSchedule.quote(RentSchedule.build(List.of(t),List.of()),1).version());}
}
